INSERT INTO survival_mastery_cards(number, category, modern, root, original_context, mechanic, field_test, namespace_name) VALUES
  (1, 1, 'The Kitchen Faucet', 'Watershed & Seepage Tracking', NULL, 'Gravity moves surface water downhill.', 'Trace three downhill routes on a contour map and compare where they meet. Use the map exercise for terrain reading only; it does not establish water safety.', 'tabor-academy-survival-001-dev'),
  (2, 1, 'Brita Water Filter', 'Bio-Sand & Charcoal Filtration', NULL, 'Particles can be captured while dissolved contaminants and microbes remain.', 'Pass clean tap water mixed with classroom soil through a paper filter. Compare clarity in two cups and discard both samples.', 'tabor-academy-survival-002-dev'),
  (3, 1, 'Thermostat & Central Heat', 'Thermal Mass & Rocket Airflow', NULL, 'Thermal mass stores heat; convection carries warm air upward.', 'Place a room-temperature stone and a dry cloth-wrapped stone in warm tap water briefly. Compare how the two cool on a tray.', 'tabor-academy-survival-003-dev'),
  (4, 1, 'Gas Stove Igniter', 'Friction & Flint Sparking', NULL, 'Friction converts motion into heat.', 'Rub your palms together for five seconds, rest, and compare the sensation with one palm held still.', 'tabor-academy-survival-004-dev'),
  (5, 1, 'Matches & Lighters', 'Char-Cloth & Tinder Nest Engineering', NULL, 'A material can catch a spark more readily when its structure exposes more surface.', 'Compare the surface area and airflow of loosely crumpled and tightly packed paper. Keep all materials unlit.', 'tabor-academy-survival-005-dev'),
  (6, 1, 'Electric Oven', 'Earth-Pit & Dutch-Oven Baking', NULL, 'Insulation slows heat transfer; an enclosed space distributes heat.', 'Compare the cooling of two cups of warm tap water on a tray, one wrapped in a towel.', 'tabor-academy-survival-006-dev'),
  (7, 1, 'Refrigerator', 'Evaporative Cooling & Root Cellars', 'Burying clay pots in shaded earth (zeer pot cooling) or digging below the frost line to keep food cold using physics instead of electricity.', 'Evaporation removes heat from a wet surface.', 'Wrap one of two identical capped bottles with a damp cloth. Compare temperatures in the same shade. Use a refrigerator for perishable food.', 'tabor-academy-survival-007-dev'),
  (8, 1, 'Ice Cubes', 'Night-Sky Radiation Freezing', 'Using shallow, insulated clay trays under clear desert or winter night skies to freeze water through radiative heat loss.', 'Surfaces exchange infrared radiation with their surroundings.', 'Compare equal shallow cups indoors under open and covered conditions and discuss which parts of the field setup this models. Use a published outdoor temperature record to examine actual freezing conditions.', 'tabor-academy-survival-008-dev'),
  (9, 1, 'Hot Water Heater', 'Solar & Coil Thermosiphoning', NULL, 'Warmer, less dense fluid can rise while cooler fluid descends.', 'Watch a density-current demonstration with warm and cool tap water and a teacher, or sketch the loop from a diagram. Use no flame or sealed heated vessel.', 'tabor-academy-survival-009-dev'),
  (10, 1, 'Ceiling Fan & AC', 'Passive Cross-Ventilation & Earth Cooling', 'Aligning low intake vents on the shaded side of a shelter with high exhaust vents on the warm side to pull cool air through automatically.', 'A pressure difference moves air through openings.', 'Cut or fold openings in a paper model and use a hand fan and tissue ribbons to compare cross-flow at two opening positions.', 'tabor-academy-survival-010-dev'),
  (11, 1, 'Smoke Detector', 'Wood-Smoke & Draft Reading', NULL, 'Smoke follows airflow; smoke alarms detect hazards the eyes may miss.', 'Use ribbon streamers and a hand fan in a cardboard model to indicate airflow. Keep working smoke alarms in service.', 'tabor-academy-survival-011-dev'),
  (12, 1, 'Fire Extinguisher', 'Smothering & Fuel-Break Trenching', NULL, 'Combustion needs heat, oxygen, and fuel.', 'Use three cards labeled heat, oxygen, and fuel to model which part each extinguisher class targets. Practise the exit route with no fire.', 'tabor-academy-survival-012-dev'),
  (13, 1, 'Pressure Cooker', 'Steam-Pit & Sealed-Clay Cooking', NULL, 'Steam transfers heat; pressure rises in a sealed heated vessel.', 'Draw the heat path on an open tabletop model. Do not heat a sealed homemade vessel.', 'tabor-academy-survival-013-dev'),
  (14, 1, 'Dehydrator', 'Sun-Rack & Smoke-Curing Preservation', NULL, 'Drying removes water from food; safe preservation depends on the process and product.', 'Weigh two wet paper towels, expose one to moving air, and weigh both again. Use tested food-preservation instructions for anything eaten.', 'tabor-academy-survival-014-dev'),
  (15, 1, 'Water Bottle', 'Gourd, Bladder & Pitch-Sealed Vessels', 'Hollowing gourds, weaving tight pitch-coated baskets, or stitching hides to carry water without leaks.', 'A seam or coating can close gaps in a vessel.', 'Fold a small paper vessel, test it over a tray with tap water, and mark where it leaks.', 'tabor-academy-survival-015-dev'),
  (16, 2, 'Google Maps & GPS', 'Cardinal Anchoring by Sun & Moss', NULL, 'The apparent path of the sun depends on time and location.', 'Record two shadow positions at a familiar site, compare with a compass, and label the difference. Moss is not a reliable compass.', 'tabor-academy-survival-016-dev'),
  (17, 2, 'Magnetic Compass', 'Magnetized Needle & Water Bowl', 'Rubbing a steel needle on silk or lodestone and floating it on a leaf in still water to find magnetic North.', 'A magnetized object can align with the local magnetic field.', 'With a teacher, float a small classroom bar magnet on cork and compare its rotation with a compass. Keep the compass clear of metal.', 'tabor-academy-survival-017-dev'),
  (18, 2, 'Wristwatch & Phone Clock', 'Shadow-Stick & Sundial Tracking', 'Driving a straight stick into level ground and marking shadow tips every hour to read time directly from Earth''s rotation.', 'A fixed object''s shadow moves as the sun''s apparent position changes.', 'Mark a stick shadow at two times and compare the recorded time and direction. Keep your eyes off the sun.', 'tabor-academy-survival-018-dev'),
  (19, 2, 'Calendar App', 'Moon-Phase & Solstice Horizon Marking', NULL, 'Lunar phases and the solar year record different cycles.', 'Chart three weeks of Moon observations and compare them with a published phase calendar. Use local frost records for planting decisions.', 'tabor-academy-survival-019-dev'),
  (20, 2, 'Weather App', 'Barometric Cloud & Wind Forecasting', NULL, 'Clouds and wind give clues; a forecast combines many measurements.', 'Write down two observations, check the local official forecast, and log what happened the next day.', 'tabor-academy-survival-020-dev'),
  (21, 2, 'Altimeter', 'Boiling-Point & Air-Pressure Sensing', NULL, 'Water boils at a lower temperature when pressure falls.', 'Compare published boiling-point data for three elevations. Plot temperature against elevation. Time-to-boil also depends on the setup.', 'tabor-academy-survival-021-dev'),
  (22, 2, 'Laser Rangefinder', 'Thumb-Jump & Shadow-Ratio Triangulation', 'Using arm-length thumb shifts and stick-shadow proportions to calculate river widths and tree heights without crossing.', 'Similar triangles connect lengths to their shadows under the same sunlight.', 'Measure a ruler''s shadow and a taller vertical object''s shadow, estimate the height, and check the estimate with a tape measure.', 'tabor-academy-survival-022-dev'),
  (23, 2, 'Night-Vision Goggles', 'Dark-Adaptation & Peripheral Scanning', 'Protecting rhodopsin in the eyes from bright light and using off-center vision to see clearly in starlight.', 'Dark adaptation changes how dim light is perceived.', 'Stay seated in a familiar dim room and compare a faint object''s appearance when you look at it directly and slightly to the side.', 'tabor-academy-survival-023-dev'),
  (24, 2, 'Flashlight', 'Pine-Resin Torches & Tallow Lamps', NULL, 'A lamp needs fuel, a way to deliver it, and oxygen.', 'Draw the fuel, wick, and air paths on a historical lamp image. Compare light distribution with a battery lamp.', 'tabor-academy-survival-024-dev'),
  (25, 2, 'Star-Gazing Apps', 'Polaris & Southern Cross Wayfinding', 'Tracing the Big Dipper''s pointer stars to Polaris (North) and tracking seasonal constellations across the night sky.', 'Reference stars can help establish direction from particular latitudes.', 'Mark reference stars on printed northern and southern sky charts. Check which chart matches your location and season.', 'tabor-academy-survival-025-dev'),
  (26, 2, 'Tide Charts', 'Lunar Pull & High-Water Driftline Reading', NULL, 'Tide height changes with location, time, and weather.', 'Compare predicted tides on a published chart for two stations. Observe a shoreline from a safe public overlook only.', 'tabor-academy-survival-026-dev'),
  (27, 2, 'Odometer', 'Pace-Counting & Ranger Beads', 'Calibrating exact step length over 100 meters on flat and sloped ground and sliding beads on a cord to track miles walked.', 'Distance is the count of steps times the average step length.', 'Mark a 10-metre path in a safe flat area. Walk it three times and compare your step estimates.', 'tabor-academy-survival-027-dev'),
  (28, 2, 'Trail Blazes', 'Cairn Stacking & Broken-Twig Signalling', 'Leaving unmistakable stone stacks, bent grass markers, or crossed sticks so anyone following knows direction and condition.', 'A consistent marker can carry direction information.', 'Make a tabletop trail map with removable arrows. Have a partner follow it without spoken directions. Leave outdoor trail markers undisturbed.', 'tabor-academy-survival-028-dev'),
  (29, 2, 'Binoculars', 'Pinhole Aperture & Horizon Scanning', 'Curving fingers into a narrow pinhole to sharpen distant shapes and scanning the horizon in slow horizontal strips.', 'A small aperture blocks some off-axis rays and dims the image.', 'Look through a pinhole in card at a printed letter across the room. Compare clarity and brightness. Never use it to look at the sun.', 'tabor-academy-survival-029-dev'),
  (30, 2, 'Sonar & Depth Finder', 'Sounding Pole & Water-Color Reading', NULL, 'Water color and ripples are affected by depth, lighting, and the bottom.', 'Put pebbles in a shallow tray, make ripples, then measure known depths with a ruler and compare appearances.', 'tabor-academy-survival-030-dev'),
  (31, 3, 'Grocery Produce Aisle', 'Wild Edible & Toxic Plant Geometry', NULL, 'Visible traits narrow an identification; they cannot prove edibility.', 'Compare leaf shapes and stems in photos of known plants with a regional field key. Keep all specimens out of the mouth.', 'tabor-academy-survival-031-dev'),
  (32, 3, 'Seed Packets', 'Heirloom Seed Saving & Fermentation', 'Fermenting tomato and squash seeds to strip germination inhibitors, drying them on paper, and storing them cool and dark.', 'Seed-saving methods differ by crop.', 'Sort packets from two known garden plants, label their collection and storage dates, and compare germination on damp paper.', 'tabor-academy-survival-032-dev'),
  (33, 3, 'Fertilizer Bags', 'Composting, Ash & Nitrogen Fixing', 'Balancing green nitrogen waste with brown carbon leaves, wood-ash potash, and legume companion planting to rebuild dead soil.', 'Decomposers need water, air, and a mix of materials.', 'Compare two tabletop diagrams of compost mixes. Identify which materials supply carbon and nitrogen and where air can enter.', 'tabor-academy-survival-033-dev'),
  (34, 3, 'Pesticide Sprays', 'Companion Planting & Beneficial Predators', 'Planting marigolds, garlic, and herbs beside crops to confuse pests and attract ladybugs and predatory wasps.', 'Plantings can support insects that act as natural predators.', 'Observe two garden plots from a path and tally insects. Record observations before drawing a conclusion about pest control.', 'tabor-academy-survival-034-dev'),
  (35, 3, 'Supermarket Meat Counter', 'Animal Track, Scat & Trail Reading', 'Identifying species, travel speed, age of tracks, and feeding patterns from impressions in mud, dust, and snow.', 'A track can record contact, size, and stride.', 'Press two known toy feet into damp sand. Measure the prints and show which observations support an identification.', 'tabor-academy-survival-035-dev'),
  (36, 3, 'Fishing Tackle Box', 'Gorge Hooks, Weirs & Hand-Spearing', NULL, 'Refraction shifts the apparent position of submerged objects.', 'Place a pencil in a clear cup of water. View it from two angles and sketch the apparent bend.', 'tabor-academy-survival-036-dev'),
  (37, 3, 'Salt Shaker', 'Seawater Evaporation & Hickory-Ash Salt', NULL, 'Evaporation leaves dissolved solids behind.', 'Let a spoonful of grocery-store salt water evaporate in a shallow tray and inspect the residue. Use no wild ash or seawater for food.', 'tabor-academy-survival-037-dev'),
  (38, 3, 'Sugar Bowl', 'Birch/Maple Tapping & Wild Honey Harvesting', NULL, 'Tree species and temperature cycles affect sap flow.', 'Compare a seasonal sap-flow chart with local temperatures and draw the route from sap to syrup. Use packaged syrup or honey for tasting.', 'tabor-academy-survival-038-dev'),
  (39, 3, 'Spice Rack', 'Wild Root, Bark & Berry Seasoning', NULL, 'Herbs differ in smell and taste, even when shapes are similar.', 'Identify and compare two labeled grocery herbs. Leave unknown plants and berries untouched.', 'tabor-academy-survival-039-dev'),
  (40, 3, 'Vitamin Supplements', 'Pine-Needle Tea & Sprouting', NULL, 'Germination changes the seed as it absorbs water.', 'Sprout classroom seeds on damp paper for observation only; log changes for three days and discard the samples.', 'tabor-academy-survival-040-dev'),
  (41, 3, 'Canned Goods', 'Lacto-Fermentation & Root-Pitting', NULL, 'Fermentation conditions affect which microbes grow.', 'Use labeled examples and compare the ingredient ratios and timelines in a tested extension recipe. Keep this exercise on paper.', 'tabor-academy-survival-041-dev'),
  (42, 3, 'Commercial Yeast', 'Wild Sourdough Starter Capture', 'Mixing flour and water in open air to capture natural airborne yeasts and lactobacilli for leavened bread.', 'Yeasts and bacteria produce gas and acids as a starter develops.', 'Observe a mature, food-safe starter in a loosely covered jar and mark its rise over time. Follow a tested recipe for any bread you eat.', 'tabor-academy-survival-042-dev'),
  (43, 3, 'Flour Mill', 'Mortar, Pestle & Saddle-Quern Grinding', NULL, 'Pressure and abrasion break dry grains into smaller particles.', 'Crush a few dry oats with a spoon in a sturdy bowl. Compare coarse and fine samples through a kitchen sieve.', 'tabor-academy-survival-043-dev'),
  (44, 3, 'Cooking Oil', 'Fat Rendering & Nut-Oil Pressing', 'Slow-simmering animal suet into clean tallow/lard or roasting and pressing walnuts and hickory nuts for oil.', 'Fats can be separated from other material by heat or pressure.', 'Compare labeled oil and fat samples at room temperature and on an ingredient chart. Press a known food sample between paper to see the grease mark.', 'tabor-academy-survival-044-dev'),
  (45, 3, 'Butcher Shop', 'Clean Field Dressing & Nose-to-Tail Use', NULL, 'Different parts of an animal have different uses and handling requirements.', 'Label edible and non-edible uses on a diagram and compare with official handling guidance. Use no raw carcass in the drill.', 'tabor-academy-survival-045-dev'),
  (46, 4, 'Nails, Screws & Glue', 'Mortise-and-Tenon & Dovetail Joinery', 'Cutting interlocking wood joints that tighten under load and hold structures together for centuries without metal fasteners.', 'Matching shapes constrain motion in more than one direction.', 'Cut matching slots in two cardboard strips and test how they resist pull compared with two overlapped strips.', 'tabor-academy-survival-046-dev'),
  (47, 4, 'Paracord & Nylon Rope', 'Reverse-Twist Plant Cordage', 'Stripping inner basswood bark, yucca fibers, or stinging nettle stalks and rolling two strands together into high-tensile rope.', 'Two twisted strands can resist unwinding when counter-twisted together.', 'Twist two pieces of paper in one direction and wrap them around each other in the other direction. Compare with a single strip.', 'tabor-academy-survival-047-dev'),
  (48, 4, 'Zip Ties & Ratchet Straps', 'Friction Knots & Trucker''s Hitches', 'Tying bowlines, taut-line hitches, and clove hitches that lock tight under tension yet untie with one pull.', 'Friction and tension affect whether a knot slides or jams.', 'Use shoelaces on a tabletop and pull gently by hand. Compare how easily two knots slide and release. Keep the drill unloaded.', 'tabor-academy-survival-048-dev'),
  (49, 4, 'Tent & Tarp', 'Debris Hut & Shingle-Bark Roofing', 'Framing a ridgepole shelter angled away from prevailing wind and layering bark slabs or leaves like roof shingles to shed heavy rain.', 'Overlapping layers shed water when each upper edge covers the joint below.', 'Build a paper-shingle roof on a tray and apply a few drops with a spoon. Compare it with reversed overlaps.', 'tabor-academy-survival-049-dev'),
  (50, 4, 'Concrete Foundation', 'Dry-Stone Stacking & Frost-Line Footings', 'Selecting flat, angular stones, overlapping seams ("one over two, two over one"), and keying corners without mortar.', 'Staggered seams distribute contact across neighboring blocks.', 'Stack foam blocks in alternating rows and in columns, then gently nudge each tabletop wall.', 'tabor-academy-survival-050-dev'),
  (51, 4, 'Bricks & Cinder Blocks', 'Cob, Adobe & Wattle-and-Daub', 'Mixing clay, sand, water, and chopped straw into monolithic walls woven over hazel branches.', 'Fibrous reinforcement changes how a mud sample cracks as it dries.', 'Shape two small air-dry clay samples, one plain and one with paper fiber, and compare their drying cracks.', 'tabor-academy-survival-051-dev'),
  (52, 4, 'Level & Plumb Bob', 'Water-Tube Level & Weighted String', 'Hanging a heavy stone on a cord for exact vertical plumb and using water in clear tubing or a trough for dead-flat horizontal leveling.', 'Gravity gives a vertical line; still water gives a level surface.', 'Hang a small washer on string beside a wall and set a clear cup of water on a tabletop. Sketch the two reference directions.', 'tabor-academy-survival-052-dev'),
  (53, 4, 'Tape Measure', 'Body-Proportion & Knotted-Cord Layout', 'Using handspans, cubits, paces, and a 12-knot rope (3-4-5 triangle) to square building corners in the dirt.', 'A triangle with sides in the ratio 3:4:5 has a right angle.', 'Build the cord loop on a tabletop and compare the target corner with the edge of a sheet of paper.', 'tabor-academy-survival-053-dev'),
  (54, 4, 'Steel Beams', 'Catenary Arches & Truss Triangulation', 'Distributing heavy overhead weight outward through stone keystones and triangular wooden trusses.', 'Triangles resist changes to their shape; arches transfer load to supports.', 'Compare triangle and square paper frames under a gentle hand nudge. Use no overhead load.', 'tabor-academy-survival-054-dev'),
  (55, 4, 'Insulation Batts', 'Dead-Air Trapping & Earth Berming', 'Banking soil against north walls and stuffing wall cavities with dry moss, wool, or straw to trap still air pockets.', 'Still air can slow heat transfer.', 'Wrap one of two warm-water cups in dry cloth and log how both cool.', 'tabor-academy-survival-055-dev'),
  (56, 4, 'Glass Windows', 'Oiled Parchment & Shutter Ventilation', 'Scraping hides thin and treating them with oil to let daylight inside while blocking wind and cold.', 'Translucent material scatters light while a shutter blocks or redirects it.', 'Cover an opening in a cardboard box with wax paper, then compare it with a sliding card shutter using a battery lamp.', 'tabor-academy-survival-056-dev'),
  (57, 4, 'Door Hinges & Locks', 'Wooden Pintle Hinges & Drop-Bar Latches', 'Carving wooden pegs that pivot in stone sockets and counterweighted wooden latches that lift with a leather pull-string.', 'A pivot allows rotation while a bar can block travel.', 'Use paper fasteners to build a pivoting cardboard flap and slide a second cardboard strip across its edge.', 'tabor-academy-survival-057-dev'),
  (58, 4, 'Cranes & Forklifts', 'A-Frame Gin Poles, Levers & Parbuckle Rolling', NULL, 'Bigger leverage can trade travel distance for force.', 'Move an eraser with a ruler resting on a pencil. Change the fulcrum position and compare the effort.', 'tabor-academy-survival-058-dev'),
  (59, 4, 'Bridges', 'Log Stringers & Woven Suspension Spans', NULL, 'Supports work in different ways under bending and tension.', 'Build a paper span and a string-supported model between books, then compare their sag with one coin.', 'tabor-academy-survival-059-dev'),
  (60, 4, 'Sewer & Septic Systems', 'Composting Latrines & Greywater Reed Beds', NULL, 'Gravel can trap particles; sanitation requires control of pathogens and pollutants.', 'Run clean colored water through gravel in a tabletop tray, compare the color, and discard it. Keep real wastewater out of the activity.', 'tabor-academy-survival-060-dev'),
  (61, 5, 'Hardware Store Blades', 'Flint Knapping & Stone Edge-Making', NULL, 'A sharp edge concentrates force at a small contact area.', 'Compare a blunt and narrow cardboard edge pressing into modelling clay. Use no sharp stone.', 'tabor-academy-survival-061-dev'),
  (62, 5, 'Electric Sharpener', 'Whetstone Angle & Leather Stropping', 'Holding a consistent 20-degree bevel on river stone and polishing the microscopic wire edge on leather.', 'Angle changes how bevels meet at an edge.', 'Fold paper angle guides and use a wooden craft stick to rehearse a consistent angle without a blade.', 'tabor-academy-survival-062-dev'),
  (63, 5, 'Power Drill', 'Pump Drill & Bow Drill Boring', 'Using a flywheel and twisted cord to spin stone or metal bits cleanly through wood, shell, and bone.', 'A cord can turn up-and-down motion into rotation.', 'Observe a toy pull-string spinner and sketch the moving parts. Use no cutting or drilling bit.', 'tabor-academy-survival-063-dev'),
  (64, 5, 'Chainsaw & Circular Saw', 'Felling Notches & Wedge Splitting', NULL, 'Wedges concentrate force and can split material along weak planes.', 'Press a cardboard wedge into modelling clay and examine the shape left behind. Do not cut standing trees.', 'tabor-academy-survival-064-dev'),
  (65, 5, 'Pottery & Dishes', 'Coil-Built Clay & Wood-Ash Glazing', NULL, 'Coils make walls when neighboring clay strands bond together.', 'Build a small air-dry clay bowl and compare its seams before and after smoothing. Keep it out of food service.', 'tabor-academy-survival-065-dev'),
  (66, 5, 'Plastic Containers', 'Steam-Bent Wood & Birch-Bark Boxes', 'Steaming thin wood strips over boiling water until pliable, bending them into boxes, and stitching seams with spruce root.', 'A flat strip can become rigid when bent and joined into a curve.', 'Bend cardstock into a box and stitch two prepunched holes with blunt yarn. Use no steam or boiling water.', 'tabor-academy-survival-066-dev'),
  (67, 5, 'Metal Foundry', 'Bloomery Furnace & Charcoal Smelting', NULL, 'Furnaces combine fuel, airflow, and insulation to sustain heat.', 'Label an archival furnace drawing with air inlet, fuel, and ore. Trace material flow with paper arrows.', 'tabor-academy-survival-067-dev'),
  (68, 5, 'Welding Torch', 'Forge Welding & Riveting', NULL, 'A rivet joins pieces by mechanically capturing them.', 'Join two strips with a brass paper fastener and compare with an overlapped unfastened pair. Leave hot metalwork to a trained shop.', 'tabor-academy-survival-068-dev'),
  (69, 5, 'Paint & Wood Stain', 'Pine-Tar, Beeswax & Iron-Vinegar Sealer', NULL, 'Some coatings cause water to bead instead of spreading into fibers.', 'Compare waxed and unwaxed paper with a drop of tap water. Use no hot tar, solvent, or chemical mix.', 'tabor-academy-survival-069-dev'),
  (70, 5, 'Superglue', 'Hide Glue & Pine-Pitch Resin Cement', NULL, 'Adhesives transfer force between joined surfaces after setting.', 'Use school glue on paper strips with two overlap sizes. Compare them after drying.', 'tabor-academy-survival-070-dev'),
  (71, 5, 'Sandpaper', 'Horsetail Rush & Sharkskin Abrasion', 'Using silica-rich scouring rush stems and sandstone blocks to polish wood and bone glass-smooth.', 'Abrasion removes high spots and changes surface texture.', 'Rub two paper or soft wood samples gently with different classroom abrasive grades, then compare surfaces.', 'tabor-academy-survival-071-dev'),
  (72, 5, 'Sewing Machine', 'Bone Awl & Saddle-Stitching', 'Punching holes in leather and sewing with two needles passing through the same hole in opposite directions so stitches never unravel.', 'Two threads can interlock in the same row of holes.', 'Lace prepunched cardstock with yarn and blunt ends. Tug gently and compare with a single lacing pattern.', 'tabor-academy-survival-072-dev'),
  (73, 5, 'Textile Factory', 'Drop-Spindle Spinning & Backstrap Looms', 'Twisting raw wool or plant fluff into uniform yarn on a weighted stick and weaving cloth on a tensioned belt loom.', 'Twist binds loose fibers into a strand; a loom holds strands under tension.', 'Twist two strands of yarn and weave them through a small cardboard loom.', 'tabor-academy-survival-073-dev'),
  (74, 5, 'Washing Machine & Soap', 'Wood-Ash Lye & Rendered-Fat Soap', NULL, 'Soap helps water lift oily material from a surface.', 'Compare plain water and commercial soap on two oily dishes. Keep caustic lye out of the activity.', 'tabor-academy-survival-074-dev'),
  (75, 5, 'Rubber Bands & Springs', 'Green-Wood Bow Limbs & Sinew Backing', NULL, 'Elastic pieces store energy as they bend.', 'Compare gentle bends in two strips of cardstock and watch how each returns. Build no bow or projectile device.', 'tabor-academy-survival-075-dev'),
  (76, 6, 'Pharmacy First Aid', 'Yarrow, Plantain & Honey Wound Care', NULL, 'Historical wound practices can be compared with modern first-aid protocols.', 'Practise opening and placing a clean dressing on a mannequin or toy. Keep plant material and raw honey out of wounds.', 'tabor-academy-survival-076-dev'),
  (77, 6, 'Painkillers & Antiseptics', 'Willow Bark & Pine-Resin Salve', NULL, 'Historical remedies and modern medicines differ in dose control and evidence.', 'Compare a labeled medicine package with a museum description. Identify dose, warnings, and ingredients on the label; ingest or apply neither preparation in this exercise.', 'tabor-academy-survival-077-dev'),
  (78, 6, 'Ambulance Splints', 'Molded Bark, Moss & Triangular Cravats', NULL, 'Padding can spread pressure; an injured limb needs appropriate assessment.', 'Model padding around a cardboard tube, not a person. For a possible fracture, seek professional help and avoid moving the injured limb unnecessarily.', 'tabor-academy-survival-078-dev'),
  (79, 6, 'Electrolyte Drinks', 'Pine-Ash, Salt & Maple-Sap Hydration', NULL, 'Electrolyte products contain specified amounts of dissolved salts.', 'Read two packaged electrolyte labels and compare their quantities. Use suitable drinking water and omit ash mixtures.', 'tabor-academy-survival-079-dev'),
  (80, 6, 'Thermometer & Fever Care', 'Cold-Water Compresses & Sweating Lodges', NULL, 'A thermometer measures temperature; sweating alone cannot establish whether a fever is resolving.', 'Compare thermometer readings for two cups of water. Keep deliberate overheating and cold exposure out of this drill.', 'tabor-academy-survival-080-dev'),
  (81, 6, 'Orthopedic Shoes', 'Barefoot Gait & Callus Conditioning', NULL, 'Surface texture affects traction and foot contact.', 'Compare impressions of two shoe soles in damp sand, then identify where each makes contact.', 'tabor-academy-survival-081-dev'),
  (82, 6, 'Gym Equipment', 'Natural Movement & Heavy Carry Mechanics', NULL, 'The position of a load changes the leverage on the body.', 'Use a lightweight empty box close to and farther from a tabletop pivot or model. Avoid heavy carries, heights, and obstacles.', 'tabor-academy-survival-082-dev'),
  (83, 6, 'Sleep Aids', 'Circadian Sunlight & Darkness Alignment', NULL, 'Light timing provides a cue for the body clock.', 'Log ordinary daylight and room-light conditions over three days. Never look directly at the sun.', 'tabor-academy-survival-083-dev'),
  (84, 6, 'Stress Medication', 'Box Breathing & Cold-Water Dive Reflex', NULL, 'Breathing pace can change perceived effort and attention.', 'While seated, count several comfortable breaths without forcing them or holding them. Do not use cold immersion or treat the drill as medication.', 'tabor-academy-survival-084-dev'),
  (85, 6, 'Toothpaste & Dental Care', 'Chew-Sticks & Charcoal/Salt Brushing', NULL, 'Brushing mechanically removes deposits from a surface.', 'Use a soft toothbrush on a model and compare the coverage with a twig sketch. Use standard dental care for teeth; leave ash and salt out.', 'tabor-academy-survival-085-dev'),
  (86, 6, 'Insect Repellent', 'Mud Coating, Smoke & Crushed Beautyberry', NULL, 'Covering skin can reduce insect access; repellents are tested for specific uses.', 'Compare a clothing barrier with a labeled repellent instruction sheet. Do not test bites or improvise a preparation on skin.', 'tabor-academy-survival-086-dev'),
  (87, 6, 'Sunscreen', 'Clay Ochre & Shade-Timing', NULL, 'Shade changes exposure, and visible color cannot verify UV protection.', 'Trace shade boundaries at different times using paper markers. Use standard sun protection outdoors.', 'tabor-academy-survival-087-dev'),
  (88, 6, 'Poison Control', 'Activated Charcoal Ingestion', NULL, 'Wood charcoal and medical activated charcoal are different; treatment depends on the exposure.', 'Use a scenario card to rehearse calling Poison Control promptly in the U.S. (1-800-222-1222). Do not ingest charcoal or try home treatment.', 'tabor-academy-survival-088-dev'),
  (89, 6, 'Hearing & Vision Protection', 'Acoustic Cupping & Snow-Goggle Slits', NULL, 'Cupped hands change incoming sound; a slit limits light from some directions.', 'Compare listening to a quiet sound with hands cupped, and look at a shaded object through slotted card. Use certified protection for actual hazards.', 'tabor-academy-survival-089-dev'),
  (90, 6, 'Emergency Rescue Beacon', 'Signal Mirrors, Smoke Columns & Ground-to-Air Glyphs', NULL, 'A rescue signal needs to stand out and reach the intended receiver.', 'Arrange high-contrast paper shapes on the ground in a safe area and sketch them from above. Use no flames, and do not make live distress signals for practice.', 'tabor-academy-survival-090-dev'),
  (91, 7, 'Smartphone Contacts', 'Memory Palace & Song-Line Recall', 'Anchoring names, directions, and inventories to physical landmarks along a familiar walking route in your mind.', 'Familiar landmarks can cue a sequence of items.', 'Assign five invented names to five familiar locations. Walk the route mentally and test recall in reverse order.', 'tabor-academy-survival-091-dev'),
  (92, 7, 'Text Messaging', 'Whistle Languages, Drum Codes & Smoke Puffs', NULL, 'A code needs agreed symbols, timing, and a way to check errors.', 'Send three messages using claps at room volume. Agree on a repeat signal. Use no smoke or live distress signals.', 'tabor-academy-survival-092-dev'),
  (93, 7, 'Cloud Storage', 'Engraved Tally Sticks & Knotted Quipu Cords', 'Carving notches into split wooden tally sticks (where both halves must match to verify a deal) and tying positional knots in cords.', 'A matching mark can act as a receipt; knot position can encode a count.', 'Give two partners matching marked card strips and make a third altered copy. Ask each to identify the matching pair.', 'tabor-academy-survival-093-dev'),
  (94, 7, 'Encryption Software', 'Cipher Wheels, Acrostics & Reverse-Reading', 'Encoding messages using letter shifts, hidden first-letter acrostics, and mirror writing readable only with the key.', 'A symbol shift is reversible when both people use the same key.', 'Make a paper alphabet wheel, encode a short made-up message, and trade with a partner. Keep real secrets out of classical ciphers.', 'tabor-academy-survival-094-dev'),
  (95, 7, 'Lie-Detector Tests', 'Micro-Expression, Baseline & Breath Reading', NULL, 'Body movements can have many causes; observations alone cannot establish deception.', 'Act out one harmless scenario two ways. Write down what was observable and what required independent evidence.', 'tabor-academy-survival-095-dev'),
  (96, 7, 'Negotiation & Law', 'Fair-Split & Restitution Protocols', 'Resolving disputes using "One divides, the other chooses" and direct repair-of-harm rather than endless bureaucracy.', 'A chooser gives the divider a reason to make reasonably balanced shares.', 'Split eight counters with one divider and one chooser. Swap roles and discuss how a lopsided split could be repaired.', 'tabor-academy-survival-096-dev'),
  (97, 7, 'Risk Management', 'Pre-Mortem Scenario Running', NULL, 'A pre-mortem starts by assuming failure and then searches for causes.', 'List how a paper bridge might fail before building it. Add one safeguard and test only the model.', 'tabor-academy-survival-097-dev'),
  (98, 7, 'Decision Fatigue', 'Binary Yes/No & Rule-of-Three Filtering', 'Stripping away non-essential noise down to three priorities: Shelter/Safety, Water/Fire, Food/Direction.', 'Constraints can identify which decisions need attention first.', 'Sort a written scenario into safety, materials, and next action. Explain which fact would change your first choice.', 'tabor-academy-survival-098-dev'),
  (99, 7, 'Information Verification', 'Primary-Source & Replication Testing', 'Refusing to trust secondhand claims until tested directly against physical reality and replicated with your own hands.', 'Independent replication tests whether a result survives the same conditions.', 'Compare two claims about an existing Academy paper bridge. Check the original setup, repeat it, and record what matched.', 'tabor-academy-survival-099-dev'),
  (100, 7, 'Emergency Alert System', 'Animal & Bird Alarm Listening', NULL, 'An alarm call can signal disturbance without identifying its cause.', 'Observe or listen to a known recording of an animal call, then list several possible causes. Verify any safety concern independently.', 'tabor-academy-survival-100-dev'),
  (101, 7, 'Self-Reliance & Sovereignty', 'The 72-Hour Zero-Gear Solo Reset', NULL, 'Self-reliance includes planning, supplies, and a reliable way to ask for help.', 'Set up a supervised tabletop or backyard skills circuit with water, supplies, a buddy, and a check-in plan. Demonstrate shelter modeling, route reading, and a signal without leaving the designated area.', 'tabor-academy-survival-101-dev')
