CREATE TABLE IF NOT EXISTS survival_mastery_cards (
  number INTEGER PRIMARY KEY CHECK (number BETWEEN 1 AND 101),
  category INTEGER NOT NULL CHECK (category BETWEEN 1 AND 7),
  modern TEXT NOT NULL, root TEXT NOT NULL, original_context TEXT,
  mechanic TEXT NOT NULL, field_test TEXT NOT NULL,
  namespace_name TEXT NOT NULL UNIQUE, namespace_id TEXT
);

CREATE TABLE IF NOT EXISTS survival_source_archive (
  content_sha256 TEXT PRIMARY KEY,
  verbatim_body TEXT NOT NULL
);

ON CONFLICT(number) DO NOTHING;
